import backtrader as bt


class VolatilityStochasticStrategy(bt.Strategy):
    def __init__(self):
        close_returns = (self.data.close / self.data.close(-1)) - 1.0
        self.volatility = bt.indicators.StdDev(close_returns, period=20)
        self.stochastic = bt.indicators.StochasticGeneric(
            self.volatility,
            period=14,
            period_dfast=3,
            period_dslow=3,
        )
        self.crossover = bt.indicators.CrossOver(
            self.stochastic.percK, self.stochastic.percD
        )
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.order = None
        self.stop_order = None

    def next(self):
        if self.order is not None:
            return

        if self.position:
            if self.position.size > 0 and self.crossover[0] < 0:
                if self.stop_order is not None:
                    self.cancel(self.stop_order)
                self.order = self.close()
            elif self.position.size < 0 and self.crossover[0] > 0:
                if self.stop_order is not None:
                    self.cancel(self.stop_order)
                self.order = self.close()
            return

        if self.stop_order is not None:
            return

        if (
            self.crossover[0] > 0
            and self.stochastic.percK[-1] < 20
            and self.volatility[0] > self.volatility[-1]
        ):
            self.order = self.buy()
        elif (
            self.crossover[0] < 0
            and self.stochastic.percK[-1] > 80
            and self.volatility[0] < self.volatility[-1]
        ):
            self.order = self.sell()

    def notify_order(self, order):
        terminal = (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        )
        if order.status not in terminal:
            return

        if order is self.stop_order:
            self.stop_order = None
            return

        if order is self.order:
            self.order = None
            if order.status == order.Completed and self.position:
                stop_distance = 2.0 * self.atr[0]
                if self.position.size > 0:
                    self.stop_order = self.sell(
                        exectype=bt.Order.Stop,
                        price=order.executed.price - stop_distance,
                    )
                else:
                    self.stop_order = self.buy(
                        exectype=bt.Order.Stop,
                        price=order.executed.price + stop_distance,
                    )
